import{_ as t,o,c as n,am as a}from"./chunks/framework.CenUaW7a.js";const g=JSON.parse('{"title":"3.27 Lesson 27: Introduction to Large Models and Conversation","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Course materials/3.27 Lesson 27 Introduction to Large Models and Conversation.md","filePath":"docs/3. Course materials/3.27 Lesson 27 Introduction to Large Models and Conversation.md"}'),i={name:"docs/3. Course materials/3.27 Lesson 27 Introduction to Large Models and Conversation.md"};function r(s,e,l,c,d,p){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="_3-27-lesson-27-introduction-to-large-models-and-conversation" tabindex="-1">3.27 Lesson 27: Introduction to Large Models and Conversation <a class="header-anchor" href="#_3-27-lesson-27-introduction-to-large-models-and-conversation" aria-label="Permalink to &quot;3.27 Lesson 27: Introduction to Large Models and Conversation&quot;">​</a></h1><h2 id="_3-27-1-lesson-introduction" tabindex="-1">3.27.1 Lesson Introduction <a class="header-anchor" href="#_3-27-1-lesson-introduction" aria-label="Permalink to &quot;3.27.1 Lesson Introduction&quot;">​</a></h2><p>As the opening lesson of the Embodied AI Large Model series, this session embarks on an exploration of large AI models. Starting with the concept of a &quot;talking encyclopedia,&quot; this lesson uses familiar examples like smart speakers and voice assistants to introduce large language models and large speech models. The lesson covers the core definitions and principles of LLMs, explaining how massive text training enables question-answering and reasoning capabilities, while showcasing mainstream platforms such as DeepSeek V4 and Doubao. Hands-on practice is structured into two stages: experiencing interactive conversations with DeepSeek, followed by configuring the K230 network and activating the Hiwonder platform to achieve real-time voice interaction. Furthermore, this lesson introduces the &quot;cloud-training, edge-inference&quot; architecture for the first time and guides through wake word interaction. As an introductory module, it lays a solid foundation for subsequent lessons on voice control and large vision models, ushering in the era of natural language interaction.</p><h2 id="_3-27-2-learning-objectives" tabindex="-1">3.27.2 Learning Objectives <a class="header-anchor" href="#_3-27-2-learning-objectives" aria-label="Permalink to &quot;3.27.2 Learning Objectives&quot;">​</a></h2><ol><li><p>Understand the core concepts and basic principles of large language models, abbreviated as LLMs. Learn the working mechanisms of speech large models and full-duplex conversational technology, and master the &quot;cloud-training and edge-inference&quot; AI deployment architecture.</p></li><li><p>Experience conversational interactions on large model platforms such as DeepSeek in a web browser. Complete Wi-Fi network connection configuration on the K230 module, and activate devices and manage intelligent agents via the hiwonder.cc platform.</p></li><li><p>Establish a natural language interaction mindset to understand the paradigm shift of AI from &quot;instruction programming&quot; to &quot;conversational interaction&quot;. Cultivate awareness of technological exploration and experience the rapid evolution and industrial transformation driven by large models.</p></li><li><p>Connect smart assistants, voice navigation, AI writing, and smart customer service to real-world application scenarios, understanding the broad value of large language models across industries.</p></li></ol><h2 id="_3-27-3-preparation" tabindex="-1">3.27.3 Preparation <a class="header-anchor" href="#_3-27-3-preparation" aria-label="Permalink to &quot;3.27.3 Preparation&quot;">​</a></h2><p><strong>Hardware Preparation</strong>:</p><ul><li>AiMecha M1 Mecanum-Wheel Car Advanced Kit</li><li>Type-C data cable</li><li>Computer × 1</li><li>Remote controller</li></ul><p><strong>Software Preparation</strong>:</p><ul><li>WonderLab graphical programming software</li></ul><p><strong>Core Concept Description</strong>:</p><ul><li><p><strong>Large Language Model or LLM</strong>: An AI system trained on massive text data capable of understanding human language, answering questions, writing, translating, programming, and reasoning, much like a &quot;scholar&quot; who has read hundreds of millions of books.</p></li><li><p><strong>Speech Large Model</strong>: AI technology that enables machines to &quot;understand&quot; human speech and &quot;synthesize&quot; natural voices, where next-generation full-duplex models support simultaneous listening and speaking for natural conversations.</p></li><li><p><strong>Cloud-Based Large Model</strong>: A large model deployed on remote servers and accessed by devices over a network, offering strong computing power that requires internet connectivity.</p></li><li><p><strong>Wake Word</strong>: The activation phrase for the voice assistant, set to &quot;Hello Hiwonder&quot; in this lesson. Once spoken, the device begins listening for commands.</p></li></ul><p><strong>Mainstream Large Model Platforms</strong>:</p><ul><li><p><strong>DeepSeek V4</strong>: Released in April 2026, supporting a 1-million-token ultra-long context window, fully open-source and free, with performance rivaling top global proprietary models.</p></li><li><p><strong>Doubao</strong>: China&#39;s largest AI application by monthly active scale, integrated with the Seed-Duplex full-duplex large speech model for lifelike conversational interaction.</p></li><li><p><strong>Other Platforms</strong>: OpenAI GPT series, Google Gemini, Baidu ERNIE, Alibaba Qwen, and Zhipu GLM series.</p></li></ul><p><strong>Wiring Instructions</strong>:</p><ul><li>Connect the K230 screen module to <strong>port A</strong> of the controller for UART serial communication.</li></ul><p><strong>K230 Network Connection and Activation Workflow</strong>:</p><ul><li><p>Step 1: Tap <strong>System Settings</strong> on the main module interface, select Wi-Fi, and enter the password to connect to the network.</p></li><li><p>Step 2: Return to the main interface and tap <strong>AI Large Model</strong>, which displays the activation page and activation code upon first launch.</p></li><li><p>Step 3: Visit hiwonder.cc in a browser → click Agent → select Manage Devices → enter the activation code to complete device binding.</p></li><li><p>Step 4: Tap AI Large Model again. The &quot;Standby&quot; screen indicates successful activation for voice conversation.</p></li></ul><p><strong>Agent Platform Features</strong>:</p><ul><li><p>Dialogue Model Configuration: Select models such as deepseek-v4-flash.</p></li><li><p>Voice Settings: Choose from multiple speech synthesis voices such as Vivi 2.0.</p></li><li><p>Speech Recognition: Powered by Alibaba Cloud ASR service.</p></li><li><p>Speech Synthesis: Powered by Volcengine Doubao TTS service.</p></li><li><p>MCP Tool Configuration: Configure functional tools that the device can invoke.</p></li></ul><h2 id="_3-27-4-hands-on-project" tabindex="-1">3.27.4 Hands-On Project <a class="header-anchor" href="#_3-27-4-hands-on-project" aria-label="Permalink to &quot;3.27.4 Hands-On Project&quot;">​</a></h2><p><strong>1. Program Logic</strong></p><p>This project builds a voice conversation system connecting the K230 with cloud-based large models, centered around edge-cloud collaborative voice interaction. The K230 microphone captures audio, the wake word &quot;Hello Hiwonder&quot; triggers listening, and the audio streams to the cloud via Wi-Fi. The cloud performs ASR speech-to-text transcription, LLM response generation, and TTS text-to-speech synthesis before returning the audio for playback. Full-duplex communication supports mid-speech interruption, while integrated MCP tool calling automatically invokes hardware interfaces such as RGB LEDs, motors, and the robotic arm when hardware commands are involved. Completing network configuration, device activation, and conversational testing establishes the concept of the edge device as the body and the cloud as the brain, illustrating the mainstream cloud-edge-terminal AIoT architecture.</p><p><strong>2. Core Operations</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">Core Operation</th><th style="text-align:left;">Functional Description</th></tr></thead><tbody><tr><td style="text-align:center;">Device activation</td><td style="text-align:left;">Tap &quot;AI Large Model&quot; and record the displayed activation code. Visit hiwonder.cc in a browser → Agent → Manage Devices → enter the activation code to complete device binding.</td></tr><tr><td style="text-align:center;">Wi-Fi connection</td><td style="text-align:left;">Tap the &quot;system settings&quot; icon on the K230 main interface, select Wi-Fi settings, and enter the Wi-Fi network name and password to connect.</td></tr></tbody></table><p><strong>3. Complete Program Description</strong></p><p><strong>Task 1: Experiencing Conversations on the DeepSeek Large Model Platform</strong></p><ul><li><p>Open a web browser and navigate to chat.deepseek.com to access the DeepSeek chat interface.</p></li><li><p>Scan the QR code with WeChat to log in, with assistance from a teacher or parent.</p></li><li><p>Enter questions in the input box, such as &quot;What is 123 plus 456 multiplied by 789?&quot;, &quot;Why can soil absorb water?&quot;, &quot;What is the smartest animal in the world?&quot;, or &quot;Write a poem about robots&quot;.</p></li><li><p>Observe the AI&#39;s response speed and quality to experience the knowledge breadth and reasoning capabilities of large language models.</p></li><li><p>Discussion and Reflection: Consider how the AI understands questions and why it can generate such accurate responses.</p></li></ul><p><strong>Task 2: K230 Module Network Configuration and Voice Conversation</strong></p><ul><li><p>Wi-Fi Connection: Tap the &quot;system settings&quot; icon on the K230 main interface, select Wi-Fi settings, and enter the Wi-Fi name and password to establish a network connection.</p></li><li><p>Device Activation: Return to the main interface, tap &quot;AI Large Model&quot;, and record the displayed activation code. Visit <code>hiwonder.cc</code> in a browser → Agent → Manage Devices → enter the activation code to bind the device.</p></li><li><p>Verify Activation: Tap &quot;AI Large Model&quot; again. The &quot;Standby&quot; screen confirms successful activation.</p></li><li><p>Voice Conversation: Utter the wake word &quot;Hello Hiwonder&quot;, wait for the prompt tone, and ask questions such as &quot;Hello, please give a self-introduction&quot;, &quot;Why did dinosaurs become extinct?&quot;, or &quot;Tell a story about a robot&quot;.</p></li><li><p>Observe and Experience: Evaluate speech recognition accuracy, response latency, and speech synthesis naturalness, comparing the performance against traditional voice assistants.</p></li></ul><p><strong>Advanced Challenge</strong></p><ul><li><p>Use the HD camera to capture objects in front of the car and use voice commands to instruct Hiwonder to identify the features of the objects ahead.</p></li><li><p>Voice Command Example: &quot;Hello Hiwonder, turn on the camera and see what is ahead&quot;.</p></li><li><p>Combine large language models with computer vision to achieve multimodal &quot;question-and-answer&quot; interaction.</p></li></ul><h2 id="_3-27-5-expansion-and-advancement" tabindex="-1">3.27.5 Expansion and Advancement <a class="header-anchor" href="#_3-27-5-expansion-and-advancement" aria-label="Permalink to &quot;3.27.5 Expansion and Advancement&quot;">​</a></h2><p><strong>Expansion Project 1: Personalized AI Assistant Robot</strong></p><p>Customize agent personas on the hiwonder.cc platform by setting Hiwonder to different roles such as a &quot;math instructor&quot;, &quot;English speaking partner&quot;, or &quot;master storyteller&quot;, and modify system prompts to adjust AI response styles and knowledge scopes. For instance, set the persona as a &quot;coding instructor&quot; for beginners so the AI explains programming concepts in simple, accessible language. Experience the customizable nature of large models and understand how system prompts shape AI behavioral patterns.</p><p><strong>Expansion Project 2: Large Model Programming Assistant Practice</strong></p><p>Explore the &quot;programming assistant&quot; or &quot;academic assistant&quot; features on the DeepSeek platform. Describe target mobile robot functions to the AI, such as &quot;writing a graphical program for line-following obstacle avoidance&quot;, and observe the generated code logic and explanations. Compare manually written programs with the AI suggestions to understand how large models assist in programming, appreciate the value of AI as a learning tool, and cultivate a &quot;human-robot interaction&quot; workflow.</p><h2 id="_3-27-6-q-a" tabindex="-1">3.27.6 Q&amp;A <a class="header-anchor" href="#_3-27-6-q-a" aria-label="Permalink to &quot;3.27.6 Q&amp;A&quot;">​</a></h2><p><strong>Q1: When prompted to write a poem about robots, the AI assistant generates verses that meet the requirements. What capability of large language models does this primarily demonstrate?</strong></p><p><strong>Answer</strong>: This primarily demonstrates the <strong>Natural Language Understanding &amp; Generation</strong> of large language models. The model not only &quot;comprehends&quot; the prompt to write a poem through natural language understanding, but also composes coherent and rhythmic verses through natural language generation.</p><p>Rather than simply predicting isolated next words, the model performs high-quality generation based on overall semantics and context. Understanding this distinction is crucial: large models do not possess &quot;thought&quot;, but instead rely on powerful language pattern learning and imitation capabilities.</p><p><strong>Q2: Why is the compact K230 module capable of conversing with such an intelligent large model?</strong></p><p><strong>Answer</strong>: The K230 module functions as an <strong>edge terminal device</strong> acting as the &quot;ears, mouth, and eyes&quot;, while the primary computing &quot;brain&quot; resides on remote cloud servers, exemplifying the classic “cloud-edge collaborative” architecture.</p><h2 id="_3-27-7-technical-support-and-discussion" tabindex="-1">3.27.7 Technical Support and Discussion <a class="header-anchor" href="#_3-27-7-technical-support-and-discussion" aria-label="Permalink to &quot;3.27.7 Technical Support and Discussion&quot;">​</a></h2><p>Join the forum for sharing questions, ideas, or suggestions, and answers will be provided promptly. Click the hyperlink <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder Forum</a> or enter the URL in a browser: <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">http://forum.hiwonder.com</a></p>',45)])])}const h=t(i,[["render",r]]);export{g as __pageData,h as default};
